    __m512d t18 = _mm512_add_pd(i0, t2);
    __m512d t19 = _mm512_add_pd(t17, t5);
    __m512d t20 = _mm512_add_pd(t18, t6);
    __m512d t21 = _mm512_add_pd(t19, t9);
